def build():
    wb = Workbook()
    head_font = Font(bold=True, color="FFFFFF")
    head_fill = PatternFill("solid", fgColor="2F6B4F")
    thin = Side(style="thin", color="BBBBBB")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    wrap = Alignment(wrap_text=True, vertical="top")

    def sheet(ws, headers, rows, widths):
        ws.append(headers)
        for r in rows:
            ws.append(list(r))
        for i, w in enumerate(widths, start=1):
            ws.column_dimensions[chr(64 + i)].width = w
        for c in ws[1]:
            c.font = head_font
            c.fill = head_fill
            c.alignment = Alignment(wrap_text=True, vertical="center")
        for row in ws.iter_rows(min_row=2):
            for c in row:
                c.alignment = wrap
                c.border = border
        ws.freeze_panes = "C2"

    ws = wb.active
    ws.title = "Mẫu việc"
    rows = [(i + 1,) + r for i, r in enumerate(ROWS)]
    sheet(ws, ["STT", "Tên công việc (theo danh sách của bạn)", "Nhóm", "Kiểu lặp", "Cần CM duyệt", "Lịch sinh việc", "Giờ", "Nội dung chi tiết (từ file)", "Ghi chú đối chiếu"],
          rows, [5, 42, 12, 20, 18, 34, 24, 90, 45])

    ws2 = wb.create_sheet("Chuỗi theo mốc")
    sheet(ws2, ["Chuỗi", "Bước", "Mốc tính", "Lệch so với mốc", "Ai làm", "Nội dung đầy đủ", "Cần CM duyệt"],
          CHAINS, [32, 6, 30, 26, 18, 100, 22])

    ws3 = wb.create_sheet("Lịch lớp Yên Hòa")
    sheet(ws3, ["Khối", "Mục", "Nội dung"], SCHED, [48, 22, 90])

    ws4 = wb.create_sheet("Ngoài danh sách")
    sheet(ws4, ["Nguồn", "Mục", "Nội dung tóm tắt từ file"], EXTRA, [18, 55, 110])

    wb.save("mau-viec-lime.xlsx")

    data = {
        "templates": [
            {"stt": i + 1, "name": r[0], "group": r[1], "repeat": r[2], "needsReview": r[3],
             "schedule": r[4], "time": r[5], "content": r[6], "note": r[7]}
            for i, r in enumerate(ROWS)],
        "chains": [
            {"chain": c[0], "step": c[1], "anchor": c[2], "offset": c[3], "owner": c[4], "content": c[5], "needsReview": c[6]}
            for c in CHAINS],
        "classSchedule": [{"block": s[0], "item": s[1], "content": s[2]} for s in SCHED],
        "notInList": [{"source": e[0], "item": e[1], "content": e[2]} for e in EXTRA],
    }
    with open("mau-viec-lime.json", "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(len(ROWS), len(CHAINS), len(SCHED), len(EXTRA))

